// swift-tools-version:5.9
import PackageDescription

// The Swift half of the contract (repo rule 2). Types and client are
// *generated* from the same `packages/api-client/openapi.json` that produces
// the TypeScript client, and the generated sources are committed — so the app
// target compiles plain Swift and no build-time plugin has to be trusted by
// xcodebuild.
//
// Regenerate with `just gen-client` (or `just gen-client-swift` alone).
// Never edit anything under Sources/GulpAPI/Generated by hand.
let package = Package(
    name: "GulpAPI",
    platforms: [.iOS(.v17), .macOS(.v14)],
    products: [
        .library(name: "GulpAPI", targets: ["GulpAPI"])
    ],
    dependencies: [
        .package(url: "https://github.com/apple/swift-openapi-generator", from: "1.0.0"),
        .package(url: "https://github.com/apple/swift-openapi-runtime", from: "1.0.0"),
        .package(url: "https://github.com/apple/swift-openapi-urlsession", from: "1.0.0"),
    ],
    targets: [
        .target(
            name: "GulpAPI",
            dependencies: [
                .product(name: "OpenAPIRuntime", package: "swift-openapi-runtime"),
                .product(name: "OpenAPIURLSession", package: "swift-openapi-urlsession"),
            ]
            // `openapi.json` and `openapi-generator-config.yaml` stay declared
            // (not excluded): the generator's command plugin finds them by
            // looking at the target's own files.
        )
    ]
)
